// 二分查找（TAB 按码点升序）
inline const G* find(uint32_t cp) {
    int lo = 0, hi = N - 1;
    while (lo <= hi) {
        const int mid = (lo + hi) / 2;
        if (TAB[mid].cp == cp) return &TAB[mid];
        if (TAB[mid].cp < cp) lo = mid + 1; else hi = mid - 1;
    }
    return nullptr;
}

